/**
 * The Expo app config. Identity comes from the build environment
 * (config/buildEnv.js) with the active shell's defaults; nothing here names
 * a brand. A fork changes the shell import below together with the one in
 * src/shell.ts.
 *
 * Assets are generated by `node scripts/brand-icons.mjs` from the shell's
 * mascot; CANVAS is core/design/tokens.ts `color.paper` (a test keeps the
 * two equal).
 */
const shell = require('./shells/donna/build');
const { resolveBuildEnv } = require('./config/buildEnv');

const CANVAS = '#FEFDFA';

module.exports = () => {
  const build = resolveBuildEnv(process.env, shell);
  const name = build.displayName;
  // One microphone string for every plugin that writes it: expo-camera and
  // expo-image-picker treat `false` as "delete the iOS string and block
  // RECORD_AUDIO on Android", which silently disabled the voice
  // introduction recorded through expo-audio.
  const microphone = `${name} uses the microphone only while you record a business introduction to prepare an editable profile.`;

  return {
    name,
    slug: shell.slug,
    version: '0.1.0',
    orientation: 'portrait',
    icon: './assets/images/icon.png',
    scheme: build.scheme,
    userInterfaceStyle: 'light',
    backgroundColor: CANVAS,
    ios: {
      bundleIdentifier: build.iosBundleIdentifier,
      supportsTablet: false
    },
    android: {
      package: build.androidPackage,
      adaptiveIcon: {
        backgroundColor: CANVAS,
        foregroundImage: './assets/images/android-icon-foreground.png',
        monochromeImage: './assets/images/android-icon-monochrome.png'
      },
      ...(build.googleServicesFile ? { googleServicesFile: build.googleServicesFile } : {}),
      predictiveBackGestureEnabled: false
    },
    web: {
      output: 'static',
      favicon: './assets/images/favicon.png'
    },
    plugins: [
      'expo-router',
      [
        'expo-splash-screen',
        {
          backgroundColor: CANVAS,
          image: './assets/images/splash-icon.png',
          imageWidth: 240
        }
      ],
      [
        'expo-camera',
        {
          cameraPermission: `${name} uses the camera to capture receipts and documents for your books.`,
          microphonePermission: microphone,
          recordAudioAndroid: false,
          barcodeScannerEnabled: false
        }
      ],
      [
        'expo-image-picker',
        {
          photosPermission: `${name} uses your photo library so you can attach receipts you already photographed.`,
          microphonePermission: microphone
        }
      ],
      [
        'expo-local-authentication',
        {
          faceIDPermission: `${name} uses Face ID to unlock your books.`
        }
      ],
      ['expo-notifications', { icon: './assets/images/notification-icon.png' }],
      'expo-secure-store',
      [
        'expo-audio',
        {
          microphonePermission: microphone,
          recordAudioAndroid: true,
          enableBackgroundRecording: false,
          // The app plays no audio. Background playback would add an iOS
          // `audio` background mode and an Android media-playback foreground
          // service, both of which the stores ask a publisher to justify.
          enableBackgroundPlayback: false
        }
      ]
    ],
    experiments: {
      typedRoutes: true
    },
    extra: {
      variant: build.variant,
      // Push tokens are issued per EAS project. Absent, push degrades to
      // "unavailable" (src/state/pushRegistration.ts) instead of failing.
      ...(build.easProjectId ? { eas: { projectId: build.easProjectId } } : {})
    }
  };
};
